16	import com.example.starter.metro.MetroRepository.BatchRow;
17	import com.example.starter.metro.MetroRepository.DetailRow;
18	import com.example.starter.metro.MetroRepository.DiscrepancyRow;
19	import com.example.starter.metro.MetroRepository.IdemRow;
20	import com.example.starter.metro.MetroRepository.TxnRow;
21	import com.example.starter.metro.dto.BatchViewResponse;
22	import com.example.starter.metro.dto.EntryRequest;
23	import com.example.starter.metro.dto.EntryResponse;
24	import com.example.starter.metro.dto.EstimateRequest;
25	import com.example.starter.metro.dto.EstimateResponse;
26	import com.example.starter.metro.dto.ExitRequest;
27	import com.example.starter.metro.dto.ExitResponse;
28	import com.example.starter.metro.dto.ReplayableResponse;
29	import com.example.starter.metro.dto.SealRequest;
30	import com.example.starter.metro.dto.SealResponse;
31	import com.fasterxml.jackson.core.JsonProcessingException;
32	import com.fasterxml.jackson.databind.ObjectMapper;
33	import org.springframework.dao.DuplicateKeyException;
34	import org.springframework.stereotype.Service;
35	import org.springframework.transaction.PlatformTransactionManager;
36	import org.springframework.transaction.support.TransactionTemplate;
37	
38	/**
39	 * 轨交清分业务服务：进闸、出闸计费、暂记与补登、跨线分摊、日结封账。
40	 * 交易与批次均以 requestId 幂等：指纹覆盖 requestId 与全部业务字段，
41	 * 同键同参返回首次结果，同键异参返回 409 且不重复入账。
42	 */
43	@Service
44	public class MetroService {
45	
46	    /** 换乘优惠窗口：出站至换乘进站 30 分钟内（含恰 30 分钟）。 */
47	    static final Duration TRANSFER_WINDOW = Duration.ofMinutes(30);
48	    /** 超时乘车阈值：进闸至出闸超过 4 小时（恰 4 小时不罚）。 */
49	    static final Duration OVERTIME_LIMIT = Duration.ofHours(4);
50	    /** 暂记分摊的占位线路编码（无法确定承运路径）。 */
51	    static final String UNALLOCATED_LINE = "UNALLOC";
52	
53	    private final MetroRepository repository;
54	    private final MileageGraph mileageGraph;
55	    private final FareCalculator fareCalculator;
56	    private final TransactionTemplate txTemplate;
57	    private final ObjectMapper objectMapper;
58	
59	    private volatile Long maxNetworkFareCents;
60	
61	    public MetroService(MetroRepository repository, MileageGraph mileageGraph,
62	                        FareCalculator fareCalculator, PlatformTransactionManager transactionManager,
63	                        ObjectMapper objectMapper) {
64	        this.repository = repository;
65	        this.mileageGraph = mileageGraph;
66	        this.fareCalculator = fareCalculator;
67	        this.txTemplate = new TransactionTemplate(transactionManager);
68	        this.objectMapper = objectMapper;
69	    }
70	
71	    /** 进闸。 */
72	    public EntryResponse entry(EntryRequest request) {
73	        String fingerprint = fingerprint("ENTRY", request.requestId(), request.txnNo(),
74	                request.cardId(), request.station(), request.entryTime().toString());
75	        return idempotent("ENTRY", request.requestId(), fingerprint, EntryResponse.class,
76	                () -> doEntry(request, fingerprint));
77	    }
78	
79	    /** 出闸；对已暂记行程执行补登（同事务冲销暂记并按实结算）。 */
80	    public ExitResponse exit(ExitRequest request) {
81	        String fingerprint = fingerprint("EXIT", request.requestId(), request.txnNo(),
82	                request.station(), request.exitTime().toString());
83	        return idempotent("EXIT", request.requestId(), fingerprint, ExitResponse.class,
84	                () -> doExit(request));
85	    }
86	
87	    /** 出闸缺失行程按最远站票价暂记。 */
88	    public EstimateResponse estimate(EstimateRequest request) {
89	        String fingerprint = fingerprint("ESTIMATE", request.requestId(), request.txnNo());
90	        return idempotent("ESTIMATE", request.requestId(), fingerprint, EstimateResponse.class,
91	                () -> doEstimate(request));
92	    }
93	
94	    /** 日结封账（终态，重复封账幂等成功）。 */
95	    public SealResponse seal(SealRequest request) {
96	        String fingerprint = fingerprint("SEAL", request.requestId(), request.bizDate().toString());
97	        return idempotent("SEAL", request.requestId(), fingerprint, SealResponse.class,
98	                () -> doSeal(request));
99	    }
100	
101	    /** 查询批次及明细、差异（逐笔复算）。 */
102	    public BatchViewResponse batchView(LocalDate bizDate) {
103	        BatchRow batch = repository.findBatchByDate(bizDate)
104	                .orElseThrow(() -> MetroException.notFound("BATCH_NOT_FOUND", "批次不存在: " + bizDate));
105	        List<DetailRow> details = repository.findDetailsByBatch(batch.id());
106	        boolean sealed = "SEALED".equals(batch.status());
107	        long total = sealed ? batch.totalCents()
108	                : details.stream().mapToLong(DetailRow::amountCents).sum();
109	        int count = sealed ? batch.txnCount() : repository.countTxnsInBatch(batch.id());
110	        List<BatchViewResponse.DetailView> detailViews = new ArrayList<>();
111	        for (DetailRow d : details) {
112	            detailViews.add(new BatchViewResponse.DetailView(d.txnNo(), d.lineCode(), d.distanceM(),
113	                    d.ratio(), d.amountCents(), d.entryType()));
114	        }
115	        List<BatchViewResponse.DiscrepancyView> discrepancyViews = new ArrayList<>();
116	        for (DiscrepancyRow d : repository.findDiscrepanciesByDate(bizDate)) {
117	            discrepancyViews.add(new BatchViewResponse.DiscrepancyView(d.txnNo(), d.amountCents(), d.reason()));
118	        }
119	        return new BatchViewResponse(batch.bizDate().toString(), batch.status(), total, count,
120	                detailViews, discrepancyViews);
121	    }
122	
123	    private EntryResponse doEntry(EntryRequest request, String fingerprint) {
124	        if (!mileageGraph.stationExists(request.station())) {
125	            throw MetroException.badRequest("STATION_UNKNOWN", "未知车站编码: " + request.station());
126	        }
127	        TxnRow row = new TxnRow(null, request.txnNo(), request.cardId(), request.station(),
128	                request.entryTime(), null, null, "ENTERED", null, 0L, null, 0L, false, false,
129	                null, null, request.requestId(), fingerprint);
130	        repository.insertTxn(row);
131	        return new EntryResponse(request.txnNo(), "ENTERED", false);
132	    }
133	
134	    private ExitResponse doExit(ExitRequest request) {
135	        TxnRow txn = repository.findTxnByNoForUpdate(request.txnNo())
136	                .orElseThrow(() -> MetroException.notFound("TXN_NOT_FOUND", "交易流水不存在: " + request.txnNo()));
137	        if ("COMPLETED".equals(txn.status())) {
138	            throw MetroException.conflict("TXN_ALREADY_COMPLETED", "交易已完成结算: " + request.txnNo());
139	        }
140	        if (request.exitTime().isBefore(txn.entryTime())) {
141	            throw MetroException.badRequest("EXIT_BEFORE_ENTRY", "出闸时间早于进闸时间");
142	        }
143	        if (!mileageGraph.stationExists(request.station())) {
144	            throw MetroException.badRequest("STATION_UNKNOWN", "未知车站编码: " + request.station());
145	        }
146	        boolean compensated = "ESTIMATED".equals(txn.status());
147	        boolean lateDiscrepancy = false;
148	
149	        if (compensated) {
150	            lateDiscrepancy = reverseEstimates(txn);
151	        }
152	
153	        MileageGraph.ShortestPath path = mileageGraph.shortestPath(txn.entryStation(), request.station());
154	        long distanceM = path.totalDistanceM();
155	
156	        long chainBaseM = 0L;
157	        boolean transfer = false;
158	        Optional<TxnRow> prev = repository.findLatestExitedTxnForCard(txn.cardId(), txn.entryTime());
159	        if (prev.isPresent()) {
160	            Duration gap = Duration.between(prev.get().exitTime(), txn.entryTime());
161	            if (!gap.isNegative() && gap.compareTo(TRANSFER_WINDOW) <= 0) {
162	                transfer = true;
163	                chainBaseM = prev.get().chainBaseM() + prev.get().distanceM();
164	            }
165	        }
166	
167	        long normalFare = fareCalculator.fareCents(chainBaseM + distanceM)
168	                - fareCalculator.fareCents(chainBaseM);
169	        long penaltyCents = 0L;
170	        if (Duration.between(txn.entryTime(), request.exitTime()).compareTo(OVERTIME_LIMIT) > 0) {
171	            penaltyCents = Math.max(0L, maxNetworkFareCents() - normalFare);
172	        }
173	        long fareCents = normalFare + penaltyCents;
174	
175	        LocalDate bizDate = request.exitTime().toLocalDate();
176	        BatchRow batch = getOrCreateBatchForUpdate(bizDate);
177	        Long batchId = batch.id();
178	        if ("SEALED".equals(batch.status())) {
179	            repository.insertDiscrepancy(new DiscrepancyRow(null, bizDate, txn.txnNo(), fareCents,
180	                    "LATE_AFTER_SEAL"));
181	            lateDiscrepancy = true;
182	            batchId = null;
183	        } else {
184	            allocate(batch.id(), txn.txnNo(), path.lineDistanceM(), distanceM, fareCents,
185	                    compensated ? "SETTLE" : "NORMAL");
186	        }
187	
188	        TxnRow updated = new TxnRow(txn.id(), txn.txnNo(), txn.cardId(), txn.entryStation(),
189	                txn.entryTime(), request.station(), request.exitTime(), "COMPLETED", distanceM,
190	                chainBaseM, fareCents, penaltyCents, transfer, false, batchId, bizDate,
191	                txn.requestId(), txn.fingerprint());
192	        repository.updateTxnSettlement(updated);
193	        return new ExitResponse(txn.txnNo(), "COMPLETED", distanceM, fareCents, penaltyCents,
194	                transfer, compensated, bizDate.toString(), lateDiscrepancy, false);
195	    }
196	
197	    /**
198	     * 冲销暂记明细：原批次未封账则在原批次内红字冲销；已封账则登记差异。
199	     *
200	     * @return 是否产生封账后差异登记
201	     */
202	    private boolean reverseEstimates(TxnRow txn) {
203	        boolean late = false;
204	        for (DetailRow estimate : repository.findDetailsByTxnAndType(txn.txnNo(), "ESTIMATE")) {
205	            BatchRow estimateBatch = repository.findBatchById(estimate.batchId())
206	                    .orElseThrow(() -> new IllegalStateException("暂记批次缺失: " + estimate.batchId()));
207	            if ("OPEN".equals(estimateBatch.status())) {
208	                repository.insertDetail(new DetailRow(null, estimate.batchId(), txn.txnNo(),
209	                        estimate.lineCode(), estimate.distanceM(), estimate.ratio(),
210	                        -estimate.amountCents(), "REVERSAL"));
211	            } else {
212	                repository.insertDiscrepancy(new DiscrepancyRow(null, estimateBatch.bizDate(),
213	                        txn.txnNo(), -estimate.amountCents(), "REVERSAL_AFTER_SEAL"));
214	                late = true;
215	            }
216	        }
217	        return late;
218	    }
219	
220	    private EstimateResponse doEstimate(EstimateRequest request) {
221	        TxnRow txn = repository.findTxnByNoForUpdate(request.txnNo())
222	                .orElseThrow(() -> MetroException.notFound("TXN_NOT_FOUND", "交易流水不存在: " + request.txnNo()));
223	        if (!"ENTERED".equals(txn.status())) {
224	            throw MetroException.conflict("TXN_STATE_CONFLICT",
225	                    "仅未出闸行程可暂记，当前状态: " + txn.status());
226	        }
227	        long estimateCents = fareCalculator.fareCents(mileageGraph.farthestDistanceM(txn.entryStation()));
228	        LocalDate bizDate = txn.entryTime().toLocalDate();
229	        BatchRow batch = getOrCreateBatchForUpdate(bizDate);
230	        Long batchId = batch.id();
231	        boolean lateDiscrepancy = false;
232	        if ("SEALED".equals(batch.status())) {
233	            repository.insertDiscrepancy(new DiscrepancyRow(null, bizDate, txn.txnNo(), estimateCents,
234	                    "ESTIMATE_AFTER_SEAL"));
235	            lateDiscrepancy = true;
236	            batchId = null;
237	        } else {
238	            repository.insertDetail(new DetailRow(null, batch.id(), txn.txnNo(), UNALLOCATED_LINE,
239	                    0L, "1.0000", estimateCents, "ESTIMATE"));
240	        }
241	        TxnRow updated = new TxnRow(txn.id(), txn.txnNo(), txn.cardId(), txn.entryStation(),
242	                txn.entryTime(), null, null, "ESTIMATED", null, 0L, estimateCents, 0L, false, true,
243	                batchId, bizDate, txn.requestId(), txn.fingerprint());
244	        repository.updateTxnSettlement(updated);
245	        return new EstimateResponse(txn.txnNo(), "ESTIMATED", estimateCents, bizDate.toString(),
246	                lateDiscrepancy, false);
247	    }
248	
249	    private SealResponse doSeal(SealRequest request) {
250	        BatchRow batch = repository.findBatchByDateForUpdate(request.bizDate())
251	                .orElseThrow(() -> MetroException.notFound("BATCH_NOT_FOUND",
252	                        "批次不存在: " + request.bizDate()));
253	        if ("SEALED".equals(batch.status())) {
254	            // 封账为终态：重复封账返回幂等成功，不改已封账合计
255	            return new SealResponse(batch.bizDate().toString(), "SEALED", batch.totalCents(),
256	                    batch.txnCount(), true);
257	        }
258	        long totalCents = repository.findDetailsByBatch(batch.id()).stream()
259	                .mapToLong(DetailRow::amountCents).sum();
260	        int txnCount = repository.countTxnsInBatch(batch.id());
261	        repository.sealBatch(batch.id(), totalCents, txnCount, request.requestId(), LocalDateTime.now());
262	        return new SealResponse(batch.bizDate().toString(), "SEALED", totalCents, txnCount, false);
263	    }
264	
265	    /**
266	     * 跨线分摊：按各线路承运里程比例（四位小数）分摊，金额取整到分，
267	     * 合计必须等于实收金额，差额归入里程最长线路。
268	     */
269	    private void allocate(long batchId, String txnNo, Map<String, Long> lineDistanceM,
270	                          long totalDistanceM, long fareCents, String entryType) {
271	        if (lineDistanceM.isEmpty()) {
272	            repository.insertDetail(new DetailRow(null, batchId, txnNo, UNALLOCATED_LINE, 0L,
273	                    "1.0000", fareCents, entryType));
274	            return;
275	        }
276	        String longestLine = lineDistanceM.entrySet().stream()
277	                .max(Comparator.<Map.Entry<String, Long>>comparingLong(Map.Entry::getValue)
278	                        .thenComparing(Map.Entry::getKey, Comparator.reverseOrder()))
279	                .orElseThrow()
280	                .getKey();
281	        long assigned = 0L;
282	        List<String> lines = lineDistanceM.keySet().stream().sorted().toList();
283	        for (String line : lines) {
284	            long lineDistance = lineDistanceM.get(line);
285	            java.math.BigDecimal ratio = java.math.BigDecimal.valueOf(lineDistance)
286	                    .divide(java.math.BigDecimal.valueOf(totalDistanceM), 4,
287	                            java.math.RoundingMode.HALF_UP);
288	            long amountCents;
289	            if (line.equals(longestLine)) {
290	                continue;
291	            }
292	            amountCents = java.math.BigDecimal.valueOf(fareCents).multiply(ratio)
293	                    .setScale(0, java.math.RoundingMode.HALF_UP).longValue();
294	            assigned += amountCents;
295	            repository.insertDetail(new DetailRow(null, batchId, txnNo, line, lineDistance,
296	                    ratio.toPlainString(), amountCents, entryType));
297	        }
298	        java.math.BigDecimal longestRatio = java.math.BigDecimal.valueOf(lineDistanceM.get(longestLine))
299	                .divide(java.math.BigDecimal.valueOf(totalDistanceM), 4,
300	                        java.math.RoundingMode.HALF_UP);
301	        repository.insertDetail(new DetailRow(null, batchId, txnNo, longestLine,
302	                lineDistanceM.get(longestLine), longestRatio.toPlainString(),
303	                fareCents - assigned, entryType));
304	    }
305	
306	    private BatchRow getOrCreateBatchForUpdate(LocalDate bizDate) {
307	        Optional<BatchRow> existing = repository.findBatchByDateForUpdate(bizDate);
308	        if (existing.isPresent()) {
309	            return existing.get();
310	        }
311	        try {
312	            repository.insertBatch(bizDate);
313	        } catch (DuplicateKeyException ex) {
314	            // 并发建批：重新加锁读取
315	        }
316	        return repository.findBatchByDateForUpdate(bizDate)
317	                .orElseThrow(() -> new IllegalStateException("批次创建失败: " + bizDate));
318	    }
319	
320	    private long maxNetworkFareCents() {
321	        Long cached = maxNetworkFareCents;
322	        if (cached == null) {
323	            synchronized (this) {
324	                if (maxNetworkFareCents == null) {
325	                    maxNetworkFareCents = fareCalculator.fareCents(mileageGraph.maxNetworkDistanceM());
326	                }
327	                cached = maxNetworkFareCents;
328	            }
329	        }
330	        return cached;
331	    }
332	
333	    private <T extends ReplayableResponse<T>> T idempotent(String scope, String requestId,
334	                                                           String fingerprint, Class<T> type,
335	                                                           Supplier<T> action) {
336	        Optional<IdemRow> existing = repository.findIdem(scope, requestId);
337	        if (existing.isPresent()) {
338	            return replay(existing.get(), fingerprint, type);
339	        }
340	        try {
341	            return txTemplate.execute(status -> {
342	                // 事务开头占位：并发同键在此阻塞或冲突，随后走重放路径
343	                repository.insertIdemPlaceholder(scope, requestId, fingerprint);
344	                T response = action.get();
345	                repository.updateIdemResponse(scope, requestId, toJson(response));
346	                return response;
347	            });
348	        } catch (DuplicateKeyException ex) {
349	            // 并发同键：以首次提交为准；否则为流水号唯一约束冲突
350	            return repository.findIdem(scope, requestId)
351	                    .map(row -> replay(row, fingerprint, type))
352	                    .orElseThrow(() -> MetroException.conflict("DUPLICATE_TXN_NO", "交易流水号重复"));
353	        }
354	    }
355	
356	    private <T extends ReplayableResponse<T>> T replay(IdemRow row, String fingerprint, Class<T> type) {
357	        if (!row.fingerprint().equals(fingerprint)) {
358	            throw MetroException.conflict("IDEMPOTENCY_CONFLICT",
359	                    "相同 requestId 但业务参数不一致，拒绝重复入账");
360	        }
361	        try {
362	            return objectMapper.readValue(row.responseBody(), type).asReplayed();
363	        } catch (JsonProcessingException ex) {
364	            throw new IllegalStateException("幂等响应反序列化失败", ex);
365	        }
366	    }
367	
368	    private String toJson(Object response) {
369	        try {
370	            return objectMapper.writeValueAsString(response);
371	        } catch (JsonProcessingException ex) {
372	            throw new IllegalStateException("幂等响应序列化失败", ex);
373	        }
374	    }
375	
376	    private String fingerprint(String scope, String... parts) {
377	        StringBuilder joined = new StringBuilder(scope);
378	        for (String part : parts) {
379	            joined.append('|').append(part);
380	        }
381	        try {
382	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
383	            byte[] hash = digest.digest(joined.toString().getBytes(StandardCharsets.UTF_8));
384	            StringBuilder hex = new StringBuilder(hash.length * 2);
385	            for (byte b : hash) {
386	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
387	                hex.append(Character.forDigit(b & 0xF, 16));
388	            }
389	            return hex.toString();
390	        } catch (NoSuchAlgorithmException ex) {
391	            throw new IllegalStateException("SHA-256 不可用", ex);
392	        }
393	    }
394	}
