28	/**
29	 * 并发与幂等边界测试：真实多线程并发调用业务服务，验证唯一约束、
30	 * 幂等重放与批次汇总在并发下的一致性。
31	 */
32	@SpringBootTest
33	class MetroConcurrencyTest {
34	
35	    @Autowired
36	    private MetroService metroService;
37	
38	    @Autowired
39	    private MetroRepository repository;
