49	        jdbcTemplate.update("DELETE FROM clearing_discrepancy");
50	        jdbcTemplate.update("DELETE FROM metro_transaction");
51	        jdbcTemplate.update("DELETE FROM clearing_batch");
52	        jdbcTemplate.update("DELETE FROM idempotency_record");
53	        executor = Executors.newFixedThreadPool(8);
54	    }
