56	    @AfterEach
57	    void tearDown() throws InterruptedException {
58	        executor.shutdown();
59	        assertTrue(executor.awaitTermination(10, TimeUnit.SECONDS));
60	    }
61	
62	    private <T> List<T> runConcurrently(int threads, java.util.function.IntFunction<T> task)
63	            throws Exception {
64	        CountDownLatch ready = new CountDownLatch(threads);
65	        CountDownLatch start = new CountDownLatch(1);
66	        List<Future<T>> futures = new ArrayList<>();
67	        for (int i = 0; i < threads; i++) {
68	            int index = i;
69	            futures.add(executor.submit(() -> {
70	                ready.countDown();
71	                assertTrue(start.await(5, TimeUnit.SECONDS));
72	                return task.apply(index);
73	            }));
74	        }
75	        assertTrue(ready.await(5, TimeUnit.SECONDS));
76	        start.countDown();
77	        List<T> results = new ArrayList<>();
78	        for (Future<T> future : futures) {
79	            results.add(future.get(15, TimeUnit.SECONDS));
80	        }
81	        return results;
82	    }
