89	
90	        long fresh = responses.stream().filter(r -> !r.replayed()).count();
91	        assertEquals(1L, fresh, "恰好一个请求实际入账，其余为重放");
92	        for (EntryResponse response : responses) {
93	            assertEquals("T-C1", response.txnNo());
94	            assertEquals("ENTERED", response.status());
