96	        Integer txnCount = jdbcTemplate.queryForObject(
97	                "SELECT COUNT(*) FROM metro_transaction WHERE txn_no = 'T-C1'", Integer.class);
98	        assertEquals(1, txnCount);
99	        Integer idemCount = jdbcTemplate.queryForObject(
100	                "SELECT COUNT(*) FROM idempotency_record WHERE scope = 'ENTRY' AND request_id = 'req-c1'",
101	                Integer.class);
102	        assertEquals(1, idemCount);
103	    }
