105	    @Test
106	    void concurrentDuplicateTxnNoAllowsExactlyOne() throws Exception {
107	        List<Object> outcomes = runConcurrently(8, i -> {
108	            try {
109	                return metroService.entry(new EntryRequest("req-c2-" + i, "T-C2", "CARD-C2", "A",
110	                        LocalDateTime.of(2026, 9, 25, 9, 0)));
111	            } catch (MetroException ex) {
112	                return ex;
113	            }
114	        });
115	        long successes = outcomes.stream().filter(o -> o instanceof EntryResponse).count();
116	        assertEquals(1L, successes, "重复流水号并发下只允许一笔入账");
117	        long conflicts = outcomes.stream()
118	                .filter(o -> o instanceof MetroException)
119	                .map(o -> (MetroException) o)
120	                .filter(ex -> ex.getStatus() == HttpStatus.CONFLICT
121	                        && "DUPLICATE_TXN_NO".equals(ex.getCode()))
122	                .count();
123	        assertEquals(7L, conflicts);
124	        Integer txnCount = jdbcTemplate.queryForObject(
125	                "SELECT COUNT(*) FROM metro_transaction WHERE txn_no = 'T-C2'", Integer.class);
126	        assertEquals(1, txnCount);
127	    }
128	
129	    @Test
130	    void concurrentExitsShareSingleBatchWithConsistentTotal() throws Exception {
131	        int trips = 6;
132	        for (int i = 0; i < trips; i++) {
133	            metroService.entry(new EntryRequest("req-c3-e" + i, "T-C3-" + i, "CARD-C3-" + i, "A",
134	                    LocalDateTime.of(2026, 9, 25, 9, 0)));
