package com.example.starter.metro.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;

/**
 * 封账后退款申请请求。
 *
 * @param requestId   幂等键
 * @param txnNo       原交易流水号（须已封账且已按实结算）
 * @param amountCents 本次退款金额（分），必须为正；累计退款不得超过原实收
 * @param reason      退款原因（合法文本可包含任意分隔符）
 * @param applicant   申请人
 */
public record RefundApplyRequest(
        @NotBlank String requestId,
        @NotBlank String txnNo,
        @Positive long amountCents,
        @NotBlank String reason,
        @NotBlank String applicant) {
}

package com.example.starter.metro.dto;

/**
 * 退款申请响应。
 *
 * @param refundNo 退款单号
 * @param txnNo    原交易流水号
 * @param amountCents 本次退款金额（分）
 * @param status   退款单状态（PENDING）
 * @param version  退款单版本（新建为 1）
 * @param replayed 是否幂等重放命中首次结果
 */
public record RefundApplyResponse(String refundNo, String txnNo, long amountCents, String status,
                                  int version, boolean replayed)
        implements ReplayableResponse<RefundApplyResponse> {

    @Override
    public RefundApplyResponse asReplayed() {
        return new RefundApplyResponse(refundNo, txnNo, amountCents, status, version, true);
    }
}

package com.example.starter.metro.dto;

import java.time.LocalDateTime;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 退款双人确认请求：两名不同复核人在同一最终确认事务内共同校验。
 *
 * @param requestId       幂等键
 * @param refundNo        退款单号
 * @param reviewer1       第一复核人
 * @param reviewer2       第二复核人（必须与第一复核人不同）
 * @param expectedVersion 退款单期望版本（乐观锁，申请成功后为 1）
 * @param confirmTime     确认精确时刻（Asia/Shanghai），参与结构化指纹
 */
public record RefundConfirmRequest(
        @NotBlank String requestId,
        @NotBlank String refundNo,
        @NotBlank String reviewer1,
        @NotBlank String reviewer2,
        @NotNull @Positive Integer expectedVersion,
        @NotNull LocalDateTime confirmTime) {
}

package com.example.starter.metro.dto;

import java.util.List;

/**
 * 退款双人确认响应：确认成功即占用行程可退余额并登记独立负向调整单。
 *
 * @param refundNo     退款单号
 * @param status       退款单状态（CONFIRMED，终态）
 * @param adjustNo     调整单号
 * @param batchId      纳入的调账批次 ID
 * @param amountCents  本次退款金额（分，正数）
 * @param allocations  按原线路实收份额分摊的负向明细
 * @param version      退款单版本（确认成功后为 2）
 * @param replayed     是否幂等重放命中首次结果
 */
public record RefundConfirmResponse(String refundNo, String status, String adjustNo, long batchId,
                                    long amountCents, List<LineAllocation> allocations, int version,
                                    boolean replayed)
        implements ReplayableResponse<RefundConfirmResponse> {

    @Override
    public RefundConfirmResponse asReplayed() {
        return new RefundConfirmResponse(refundNo, status, adjustNo, batchId, amountCents,
                allocations, version, true);
    }

    /**
     * 单线路调整分摊。
     *
     * @param lineCode    线路编码
     * @param amountCents 负向调整金额（分）
     */
    public record LineAllocation(String lineCode, long amountCents) {
    }
}

package com.example.starter.metro.dto;

import java.time.LocalDateTime;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 调账批次封存请求：封存后只读。
 *
 * @param requestId       幂等键
 * @param expectedVersion 开放调账批次期望版本（乐观锁）
 * @param sealTime        封存精确时刻（Asia/Shanghai），参与结构化指纹
 */
public record AdjustSealRequest(
        @NotBlank String requestId,
        @NotNull @Positive Integer expectedVersion,
        @NotNull LocalDateTime sealTime) {
}

package com.example.starter.metro.dto;

import java.util.List;

/**
 * 调账批次封存响应。
 *
 * @param batchId     批次 ID
 * @param status      批次状态（SEALED，终态）
 * @param totalCents  批次合计快照（分，负数）
 * @param orderCount  批次内调整单笔数
 * @param version     批次版本（封存成功加 1）
 * @param details     批次内全部调整单及其线路明细（封存证据）
 * @param replayed    是否幂等重放命中首次结果
 */
public record AdjustSealResponse(long batchId, String status, long totalCents, int orderCount,
                                 int version, List<AdjustOrderView> details, boolean replayed)
        implements ReplayableResponse<AdjustSealResponse> {

    @Override
    public AdjustSealResponse asReplayed() {
        return new AdjustSealResponse(batchId, status, totalCents, orderCount, version, details, true);
    }

    /**
     * 调整单视图。
     *
     * @param adjustNo    调整单号
     * @param refundNo    来源退款单号
     * @param txnNo       原交易流水号
     * @param amountCents 调整合计（分，负数）
     * @param lines       线路级负向明细
     */
    public record AdjustOrderView(String adjustNo, String refundNo, String txnNo, long amountCents,
                                  List<RefundConfirmResponse.LineAllocation> lines) {
    }
