static Map<String, Long> allocate(Map<String, Long> shares, Map<String, Long> refunded,
                                  long fareCents, long amount) {
    List<String> order = shares.keySet().stream()
        .sorted(Comparator.<String>comparingLong(shares::get).reversed().thenComparing(Comparator.naturalOrder()))
        .toList();
    Map<String, Long> alloc = new LinkedHashMap<>();
    long assigned = 0;
    for (String line : order) {
        long base = amount * shares.get(line) / fareCents;  // 向下取整（正数）
        long capacity = shares.get(line) - refunded.getOrDefault(line, 0L);
        long a = Math.min(base, capacity);
        alloc.put(line, a);
        assigned += a;
    }
    long remainder = amount - assigned;
    while (remainder > 0) {
        for (String line : order) {
            if (remainder == 0) break;
            long capacity = shares.get(line) - refunded.getOrDefault(line, 0L);
            if (alloc.get(line) < capacity) {
                alloc.put(line, alloc.get(line) + 1);
                remainder--;
            }
        }
    }
    return alloc;
}
