        return refundService.sealAdjustBatch(request);
    }

    /** 逐线路退款余额查询。 */
    @GetMapping("/balance/{txnNo}")
    public RefundBalanceResponse balance(@PathVariable String txnNo) {
        return refundService.balance(txnNo);
    }
}

