    @Test
    void sameReviewerAndWrongVersionAndAlreadyConfirmedAreRejected() throws Exception {
        prepareSealedTrip();
        JsonNode applied = refundApply("ra8", "T1", 100, "x", "alice", 200);
        String refundNo = applied.get("refundNo").asText();

