private JsonNode refundConfirm(String requestId, String refundNo, String r1, String r2,
                               int expectedVersion, String confirmTime, int expectedStatus)
        throws Exception {
    String body = "{\"requestId\":\"%s\",\"refundNo\":\"%s\",\"reviewer1\":\"%s\",\"reviewer2\":\"%s\","
            + "\"expectedVersion\":%d,\"confirmTime\":\"%s\"}"
            .formatted(requestId, refundNo, r1, r2, expectedVersion, confirmTime);
